public class ExtractMethodAnalyzerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void finish() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    static java.util.List<String> list(String... values) {
        return new java.util.ArrayList<>(java.util.Arrays.asList(values));
    }

    static final java.util.List<String> SCOPE = list("total", "items", "tax", "label", "count");

    public static void main(String[] args) {
        java.util.List<String> block = list("total = 0;", "total = items * tax;");
        check("parameters of a simple block", "[items, tax]",
                String.valueOf(ExtractMethodAnalyzer.parameters(SCOPE, block)));
        check("writes of a simple block", "[total]",
                String.valueOf(ExtractMethodAnalyzer.writes(SCOPE, block)));
        check("returnVariable of a simple block", "total",
                ExtractMethodAnalyzer.returnVariable(SCOPE, block));

        java.util.List<String> loop = list(
                "for (int i = 0; i < items; i++) {",
                "count += 1;",
                "}",
                "System.out.println(label);");
        check("compound assignment counts as a read", "[count, items, label]",
                String.valueOf(ExtractMethodAnalyzer.parameters(SCOPE, loop)));
        check("a block that writes nothing", "void",
                ExtractMethodAnalyzer.returnVariable(SCOPE, loop));

        java.util.List<String> two = list("total = 1;", "count = 2;");
        check("two writes are ambiguous", "AMBIGUOUS",
                ExtractMethodAnalyzer.returnVariable(SCOPE, two));
        check("writes keeps first-write order", "[total, count]",
                String.valueOf(ExtractMethodAnalyzer.writes(SCOPE, two)));

        java.util.List<String> tricky = list("if (total == count) {", "label = \"tie\";", "}");
        check("== is a comparison, not an assignment", "[count, total]",
                String.valueOf(ExtractMethodAnalyzer.parameters(SCOPE, tricky)));
        check("only the real assignment is a write", "label",
                ExtractMethodAnalyzer.returnVariable(SCOPE, tricky));

        java.util.List<String> longer = list("totalCount = totals + 1;");
        check("longer names are not matched", "[]",
                String.valueOf(ExtractMethodAnalyzer.parameters(SCOPE, longer)));
        finish();
    }
}

