public class ExtractMethodAnalyzer {

    public static java.util.List<String> parameters(java.util.List<String> inScope,
                                                    java.util.List<String> block) {
        java.util.List<String> reads = new java.util.ArrayList<>();
        for (String line : block) {
            String text = line.trim();
            String target = assignmentTarget(text);
            String readPart = target == null ? text : text.substring(text.indexOf('=') + 1);
            for (String name : inScope) {
                if (!reads.contains(name) && containsIdentifier(readPart, name)) {
                    reads.add(name);
                }
            }
        }
        java.util.Collections.sort(reads);
        return reads;
    }

    public static java.util.List<String> writes(java.util.List<String> inScope,
                                                java.util.List<String> block) {
        java.util.List<String> written = new java.util.ArrayList<>();
        for (String line : block) {
            String target = assignmentTarget(line.trim());
            if (target != null && inScope.contains(target) && !written.contains(target)) {
                written.add(target);
            }
        }
        return written;
    }

    public static String returnVariable(java.util.List<String> inScope,
                                        java.util.List<String> block) {
        java.util.List<String> written = writes(inScope, block);
        if (written.isEmpty()) {
            return "void";
        }
        if (written.size() > 1) {
            return "AMBIGUOUS";
        }
        return written.get(0);
    }

    private static String assignmentTarget(String text) {
        int i = 0;
        while (i < text.length() && isIdentifierPart(text.charAt(i))) {
            i++;
        }
        if (i == 0) {
            return null;
        }
        String name = text.substring(0, i);
        while (i < text.length() && text.charAt(i) == ' ') {
            i++;
        }
        if (i >= text.length() || text.charAt(i) != '=') {
            return null;
        }
        if (i + 1 < text.length() && text.charAt(i + 1) == '=') {
            return null;
        }
        return name;
    }

    private static boolean containsIdentifier(String text, String name) {
        int i = text.indexOf(name);
        while (i >= 0) {
            boolean beforeOk = i == 0 || !isIdentifierPart(text.charAt(i - 1));
            int after = i + name.length();
            boolean afterOk = after >= text.length() || !isIdentifierPart(text.charAt(after));
            if (beforeOk && afterOk) {
                return true;
            }
            i = text.indexOf(name, i + 1);
        }
        return false;
    }

    private static boolean isIdentifierPart(char c) {
        return Character.isLetterOrDigit(c) || c == '_' || c == '$';
    }
}
